interface TechIconCardProps {
  name: string;
  icon: string;
}

export function TechIconCard({ name, icon }: TechIconCardProps) {
  const [hovered, setHovered] = useState(false);
  const cardRef = useRef<HTMLDivElement>(null);
  const iconData = SKILL_ICONS[icon] ?? SKILL_ICONS[name.toLowerCase()];

  return (
    <div
      ref={cardRef}
      className="tech-icon-card"
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      role="img"
      aria-label={name}
      style={{
        boxShadow: hovered
          ? `0 8px 32px ${iconData?.color ?? "#3b7eff"}18, 0 0 0 1px ${iconData?.color ?? "#3b7eff"}22`
          : "none",
      }}
    >
      {/* Icon */}
      <div
        style={{
          width: "36px",
          height: "36px",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          transition: "transform 0.3s var(--ease-spring), filter 0.3s ease",
          transform: hovered ? "scale(1.18)" : "scale(1)",
          filter: hovered
            ? `drop-shadow(0 0 6px ${iconData?.color ?? "#3b7eff"}80)`
            : "none",
        }}
      >
        {iconData ? (
          <div dangerouslySetInnerHTML={{ __html: iconData.svg }} />
        ) : (
          <span style={{ fontSize: "1.1rem", fontWeight: 800, color: "#3b7eff" }}>
            {name.charAt(0)}
          </span>
        )}
      </div>

      {/* Name */}
      <span
        style={{
          fontSize: "0.68rem",
          fontWeight: 500,
          letterSpacing: "0.02em",
          color: hovered ? "var(--text-primary)" : "var(--text-secondary)",
          transition: "color 0.2s ease",
          textAlign: "center",
          lineHeight: 1.2,
        }}
      >
        {name}
      </span>
    </div>
  );
}
